  width: 100%;
  display: flex;
  gap: 16px;
  padding: 16px;
  box-sizing: border-box;
  border-radius: 14px;
  background: rgba(251, 245, 240, 0.8);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08);
  border: 1px solid rgba(0, 0, 0, 0.06);
}

.seal-node-detail-left {
  width: 140px;
  min-width: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.seal-node-detail-image-wrapper {
  width: 120px;
  height: 120px;
  border-radius: 12px;
  background: #f5f5f5;
  border: 1px solid #e6e6e6;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.seal-node-detail-image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.seal-node-detail-right {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

.seal-node-detail-title {
  font-size: 20px;
  font-weight: 700;
  color: #111111;
  line-height: 1.3;
  margin-bottom: 16px;
  word-break: break-word;
}

.seal-node-detail-info-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.seal-node-detail-info-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 10px;
  background: #f8f9fb;
}

.seal-node-detail-label {
  font-size: 13px;
  font-weight: 600;
  color: #666666;
}

.seal-node-detail-value {
  font-size: 15px;
  line-height: 1.6;
  color: #222222;
  word-break: break-word;
